import{_ as o,a0 as s,w as m,s as c,ao as n,I as p,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 SNMP 和 Cacti 監控 Linux 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 SNMP 和 Cacti 監控 Linux 服務器 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 SNMP 和 Cacti 監控 Linux 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 SNMP 和 Cacti 監控 Linux 服務器 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150601 How to monitor Linux servers with SNMP and Cacti","title":"使用 SNMP 和 Cacti 監控 Linux 服務器","tag":"201507","desc":""},"relativePath":"201507/20150601 How to monitor Linux servers with SNMP and Cacti.md","filePath":"[post].md"}'),l={name:"201507/20150601 How to monitor Linux servers with SNMP and Cacti.md"};function d(f,t,u,h,g,_){const r=s("Link");return m(),c("div",null,[t[16]||(t[16]=n(`<h1 id="使用-snmp-和-cacti-監控-linux-服務器" tabindex="-1">使用 SNMP 和 Cacti 監控 Linux 服務器 <a class="header-anchor" href="#使用-snmp-和-cacti-監控-linux-服務器" aria-label="Permalink to “使用 SNMP 和 Cacti 監控 Linux 服務器”">​</a></h1><p>SNMP（簡單網絡管理協議）用於收集設備內部發生的數據，如負載、磁盤狀態、帶寬之類。像Cacti這樣的網絡監控工具用這些數據來生成圖標以達到監控的目的。</p><p>在一個典型的Cacti和SNMP部署中，會有一台或多台啓用了SNMP的設備，以及一台獨立的用來從那些設備收集SNMP回饋的監控服務器。請記住，所有需要監控的設備必須啓用SNMP。在本教程中，出於演示目的，我們將在同一台Linux服務器上配置Cacti和SNMP。</p><h3 id="在debian或ubuntu上配置snmp" tabindex="-1">在Debian或Ubuntu上配置SNMP <a class="header-anchor" href="#在debian或ubuntu上配置snmp" aria-label="Permalink to “在Debian或Ubuntu上配置SNMP”">​</a></h3><p>要在基於Debian的系統上安裝SNMP代理（snmpd），請運行以下命令：</p><pre><code>root@server:~# apt-get install snmpd
</code></pre><p>然後，如下編輯配置文件。</p><pre><code>root@server:~# vim /etc/snmp/snmpd.conf
</code></pre><hr><pre><code># 使snmpd 監聽再所有接口上
agentAddress  udp:161

# 定義一個只讀的 community &#39;myCommunity&#39; 和源網絡
rocommunity myCommunity 172.17.1.0/24

sysLocation    Earth
sysContact     email@domain.tld
</code></pre><p>在編輯完配置文件後，重啓snmpd。</p><pre><code>root@server:~# service snmpd restart
</code></pre><h3 id="在centos或rhel上配置snmp" tabindex="-1">在CentOS或RHEL上配置SNMP <a class="header-anchor" href="#在centos或rhel上配置snmp" aria-label="Permalink to “在CentOS或RHEL上配置SNMP”">​</a></h3><p>要安裝SNMP工具和庫，請運行以下命令。</p><pre><code>root@server:~# sudo yum install net-snmp
</code></pre><p>然後，如下編輯SNMP配置文件。</p><pre><code>root@server:~# vim /etc/snmp/snmpd.conf
</code></pre><hr><pre><code># 定義一個使用 community &#39;myCommunity&#39; 和源網絡 172.17.1.0/24 的用户 &#39;myUser&#39;
com2sec myUser 172.17.1.0/24 myCommunity

# 將 myUser 加到 &#39;myGroup&#39; 組，定義組權限
group    myGroup    v1        myUser
group    myGroup    v2c        myUser
view all included .1
access myGroup    &quot;&quot;    any    noauth     exact    all    all    none
</code></pre><hr><pre><code>root@server:~# service snmpd restart
root@server:~# chkconfig snmpd on
</code></pre><p>重啓snmpd服務，然後添加到啓動服務列表。</p><h3 id="測試snmp" tabindex="-1">測試SNMP <a class="header-anchor" href="#測試snmp" aria-label="Permalink to “測試SNMP”">​</a></h3><p>SNMP可以通過運行snmpwalk命令進行測試。如果SNMP已經配置成功，該命令會生成大量輸出。</p><pre><code>root@server:~# snmpwalk -c myCommunity 172.17.1.44 -v1
</code></pre><hr><pre><code>iso.3.6.1.2.1.1.1.0 = STRING: &quot;Linux mrtg 3.5.0-17-generic #28-Ubuntu SMP Tue Oct 9 19:31:23 UTC 2012 x86_64&quot;
iso.3.6.1.2.1.1.2.0 = OID: iso.3.6.1.4.1.8072.3.2.10
iso.3.6.1.2.1.1.3.0 = Timeticks: (2097) 0:00:20.97

~~ 輸出截斷 ~~

iso.3.6.1.2.1.92.1.1.2.0 = Gauge32: 1440
iso.3.6.1.2.1.92.1.2.1.0 = Counter32: 1
iso.3.6.1.2.1.92.1.2.2.0 = Counter32: 0
iso.3.6.1.2.1.92.1.3.1.1.2.7.100.101.102.97.117.108.116.1 = Timeticks: (1) 0:00:00.01
iso.3.6.1.2.1.92.1.3.1.1.3.7.100.101.102.97.117.108.116.1 = Hex-STRING: 07 DD 0B 12 00 39 27 00 2B 06 00 
</code></pre><h3 id="配置帶有snmp的cacti" tabindex="-1">配置帶有SNMP的Cacti <a class="header-anchor" href="#配置帶有snmp的cacti" aria-label="Permalink to “配置帶有SNMP的Cacti”">​</a></h3><p>在本教程中，我們將在同一台Linux服務器上設置Cacti和SNMP。所以，到剛剛配置SNMP的Linux服務器上去[安裝Cacti][2]吧。</p>`,29)),p("p",null,[t[1]||(t[1]=a("安裝完後，Cacti網頁界面可以通過“",-1)),i(r,{href:"http://172.17.1.44/cacti"},{default:e(()=>[...t[0]||(t[0]=[a("http://172.17.1.44/cacti",-1)])]),_:1}),t[2]||(t[2]=a(" ”來訪問，當然，在你的環境中，請將IP地址換成你的服務器的地址。",-1))]),t[17]||(t[17]=n('<p><img src="http://farm6.staticflickr.com/5512/10972747655_0298f6ce6c_z.jpg" alt=""></p><p><img src="http://farm6.staticflickr.com/5532/10972982543_67e15433b8_z.jpg" alt=""></p><p>安裝過程中Cacti的路徑一般都是正確的，但是如有必要，請再次檢查以下。</p><p><img src="http://farm4.staticflickr.com/3764/10972920304_138670d3cf_z.jpg" alt=""></p><p>在首次安裝過程中，Cacti默認的用户名和密碼是“admin”和“admin”。在首次登錄後會強制你修改密碼。</p><p><img src="http://farm6.staticflickr.com/5542/10972747775_531fe445ef_o.png" alt=""></p><h3 id="添加設備到cacti並管理" tabindex="-1">添加設備到Cacti並管理 <a class="header-anchor" href="#添加設備到cacti並管理" aria-label="Permalink to “添加設備到Cacti並管理”">​</a></h3><p>Cacti將根據先前配置的SNMP字符串註冊設備。在本教程中，我們將只添加啓用了SNMP的本地服務器。</p><p>要添加設備，我們必須以管理員登錄，然後轉到Cacti管理員面板中的控制台。點擊 控制台 &gt; 設備。</p><p><img src="http://farm8.staticflickr.com/7411/10972747855_b464972e56_z.jpg" alt=""></p><p>那裏可能已經有一個名為‘localhost’的設備。我們不需要它，因為我們要創建全新的圖表。我們可以將該設備從列表中刪除，使用“添加”按鈕來添加新設備。</p><p><img src="http://farm8.staticflickr.com/7373/10972747895_977e0eccd6_z.jpg" alt=""></p><p>接下來，我們設置設備參數。</p><p><img src="http://farm8.staticflickr.com/7400/10972747935_df03500de7_z.jpg" alt=""></p><p>現在設備已經添加，我們來指定想要創建的圖表模板。你可以在該頁面的最後部分中找到這塊內容。</p><p><img src="http://farm4.staticflickr.com/3773/10972747955_083101e6ab_z.jpg" alt=""></p><p>然後，我們繼續來創建圖表。</p><p><img src="http://farm4.staticflickr.com/3734/10972747985_fae6b78888.jpg" alt=""></p><p>這裏，我們創建用於平均負載、RAM和硬盤、處理器的圖表。</p><p><img src="http://farm8.staticflickr.com/7374/10972920484_ed6b33b8b8_z.jpg" alt=""></p><h3 id="接口的圖表和64位計數器" tabindex="-1">接口的圖表和64位計數器 <a class="header-anchor" href="#接口的圖表和64位計數器" aria-label="Permalink to “接口的圖表和64位計數器”">​</a></h3><p>默認情況下，Cacti在SNMP查詢中使用32位計數器。32位計數器對於大多數帶寬圖表而言已經足夠了，但是對於超過100Mbps的帶寬，它就無能為力了。如果已經知道帶寬會超過100Mbps，建議你使用64位計數器。使用64位計數器一點也不麻煩。</p><p><img src="http://farm8.staticflickr.com/7320/10972982813_120fe1f3d0_z.jpg" alt=""></p><p><strong>注意</strong>： Cacti會花費大約15分鐘來產生新圖表，除了耐心等待，你別無選擇。</p><h3 id="創建圖表樹" tabindex="-1">創建圖表樹 <a class="header-anchor" href="#創建圖表樹" aria-label="Permalink to “創建圖表樹”">​</a></h3><p>這些截圖展示瞭如何創建圖表樹，以及如何添加圖表到這些樹中。</p><p><img src="http://farm8.staticflickr.com/7429/10972748045_ca06bec889_z.jpg" alt=""></p><p><img src="http://farm3.staticflickr.com/2833/10972920584_f33624862a_z.jpg" alt=""></p><p><img src="http://farm6.staticflickr.com/5548/10972836666_f31e4de0e7_z.jpg" alt=""></p><p><img src="http://farm4.staticflickr.com/3786/10972836776_1675611740_z.jpg" alt=""></p><p>我們可以驗證圖表樹中的圖表。</p><p><img src="http://farm4.staticflickr.com/3707/10972836836_3dabe56765_z.jpg" alt=""></p><h3 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to “用户管理”">​</a></h3><p>最後，我們創建一個只具有查看我們剛創建的圖表權限的用户。Cacti內建了用户管理系統，而且是高度可定製的。</p><p><img src="http://farm8.staticflickr.com/7313/10972920624_61e13157f9_z.jpg" alt=""></p><p><img src="http://farm6.staticflickr.com/5536/10972920644_59a9797685_z.jpg" alt=""></p><p><img src="http://farm3.staticflickr.com/2872/10972920744_24f75fb5a8_z.jpg" alt=""></p><p>在完成這些步驟後，我們可以使用‘user1’來登錄進去，並驗證只有該用户可以查看該圖表。</p><p><img src="http://farm8.staticflickr.com/7423/10972748265_c2608b3683_z.jpg" alt=""></p><p><img src="http://farm4.staticflickr.com/3763/10972748335_9cd012c6fe_z.jpg" alt=""></p><p>至此，我們在網絡監控系統中部署了一台Cacti服務器。Cacti服務器比較穩定，可以處理大量圖表而不會出問題。</p><p>希望本文對你有所幫助。</p><hr>',43)),p("p",null,[t[4]||(t[4]=a("via: ",-1)),i(r,{href:"http://xmodulo.com/monitor-linux-servers-snmp-cacti.html"},{default:e(()=>[...t[3]||(t[3]=[a("http://xmodulo.com/monitor-linux-servers-snmp-cacti.html",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=a("作者：",-1)),i(r,{href:"http://xmodulo.com/author/sarmed"},{default:e(()=>[...t[5]||(t[5]=[a("Sarmed Rahman",-1)])]),_:1}),t[9]||(t[9]=a(" 譯者：",-1)),i(r,{href:"https://github.com/GOLinux"},{default:e(()=>[...t[6]||(t[6]=[a("GOLinux",-1)])]),_:1}),t[10]||(t[10]=a(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[a("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=a("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原創翻譯，",-1)),i(r,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[a("Linux中國",-1)])]),_:1}),t[15]||(t[15]=a(" 榮譽推出",-1))])])}const S=o(l,[["render",d]]);export{x as __pageData,S as default};
